class Solution:
    def minWindow(self, s: str, t: str) -> str:
        need = Counter(t)
        window: Counter[str] = Counter()
        met = 0  # characters of t the window holds enough of
        best_l, best_len = 0, len(s) + 1
        l = 0
        for r, c in enumerate(s):
            window[c] += 1  # viz:grow
            if c in need and window[c] == need[c]:
                met += 1  # viz:met
            while met == len(need):
                if r - l + 1 < best_len:  # viz:cover
                    best_l, best_len = l, r - l + 1  # viz:record
                out = s[l]
                window[out] -= 1  # viz:shrink
                if out in need and window[out] < need[out]:
                    met -= 1  # viz:lost
                l += 1
        if best_len > len(s):
            return ""  # viz:none
        return s[best_l : best_l + best_len]  # viz:done
